import json
from pathlib import Path
import struct
import sys
import tempfile
import unittest

sys.path.insert(0, str(Path(__file__).parents[2] / 'tools'))
import icon256_app_market as market
from test_release import image


class AppMarketTests(unittest.TestCase):
    def test_factory_layout_and_corruption(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            boot = bytearray(24)
            boot[0] = 0xE9
            struct.pack_into('<H', boot, 12, 9)
            (root / 'bootloader.bin').write_bytes(boot)
            table = bytearray(0xc00)
            for i, row in enumerate([(1, 2, 0x9000, 0x5000), (1, 0, 0xe000, 0x2000),
                                     (0, 16, 0x10000, 0x180000), (0, 17, 0x190000, 0x180000),
                                     (1, 130, 0x310000, 0xf0000)]):
                struct.pack_into('<HBBII', table, i * 32, 0x50AA, *row)
            (root / 'partitions.bin').write_bytes(table)
            (root / 'firmware.bin').write_bytes(image())
            (root / 'boot_app0.bin').write_bytes(b'\xff' * 0x2000)
            icon = Path(__file__).parents[2] / 'tools/icon256-assets/icon256.png'
            out = root / 'release'
            market.package('v1.2.3', root, root / 'boot_app0.bin', icon, out)
            manifest = json.loads((out / 'app-market.json').read_text())
            factory = out / manifest['release']['partitions'][0]['asset']
            data = factory.read_bytes()
            self.assertEqual(data[0x10000:], image())
            self.assertEqual(data[0x9000:0xe000], b'\xff' * 0x5000)
            with self.assertRaises(ValueError):
                market.inspect_factory(data, '1.2.4')
            corrupt = bytearray(data)
            corrupt[0x8000] ^= 1
            with self.assertRaises(ValueError):
                market.inspect_factory(corrupt, '1.2.3')
            corrupt = bytearray(data)
            corrupt[0x100] ^= 1  # Also detect damage outside application metadata.
            factory.write_bytes(corrupt)
            with self.assertRaisesRegex(ValueError, 'SHA-256'):
                market.verify(out / 'app-market.json')
            (root / 'bootloader.bin').write_bytes(b'x' * 0x8001)
            with self.assertRaisesRegex(ValueError, 'oversized'):
                market.package('v1.2.3', root, root / 'boot_app0.bin', icon, out)
